import {defaults,palette,validateIdeas,uniform,targetRotation,distance,navigationURL} from './core.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let ideas=[...defaults];try{const saved=JSON.parse(localStorage.getItem('just-pick.user-ideas.v2'));if(Array.isArray(saved)&&saved.every(x=>typeof x==='string')&&!validateIdeas(saved,0))ideas=saved;}catch{}
let page='ideas',choice=null,busy=false,rotation=0,location=null,radius=3,shops=[],selected=null,status='idle',message='',source='',provider='baidu',requestId=0,controller=null,locationRequest=0;
const titles={ideas:'就这么定',wheel:'转一下决定吧',result:'转盘结果',shops:'选一家，一起去',destination:'准备出发'};
const previous={wheel:'ideas',result:'wheel',shops:'result',destination:'shops'};
function invalidateShops(){requestId++;controller?.abort();shops=[];selected=null;source='';status='idle';message='';}
function changed(){choice=null;rotation=0;invalidateShops();try{localStorage.setItem('just-pick.user-ideas.v2',JSON.stringify(ideas));}catch{}}
function move(next,push=true){if(busy)return;stopCelebration();if((next==='result'||next==='shops')&&!choice)next='wheel';if(next==='destination'&&!selected)next='shops';page=next;if(push)history.pushState({page},'',`#${page}`);render();$('#app h1')?.focus({preventScroll:true});}
history.replaceState({page:'ideas'},'','#ideas');
window.addEventListener('popstate',event=>{if(busy){history.pushState({page:'wheel'},'','#wheel');return;}move(event.state?.page in titles?event.state.page:'ideas',false);});
function render(){app.className=page==='wheel'?'wheel-page':'';app.innerHTML=`<header class="appnav">${page==='ideas'?'<span class="nav-space"></span>':`<button class="back" aria-label="返回${titles[previous[page]]}" ${busy?'disabled':''}>‹</button>`}<h1 tabindex="-1">${titles[page]}</h1><span class="nav-space"></span></header>`;
 if(page==='ideas')renderIdeas();if(page==='wheel')renderWheel();if(page==='result')renderResult();if(page==='shops')renderShops();if(page==='destination')renderDestination();$('.back')?.addEventListener('click',()=>move(previous[page]));}
function renderIdeas(){app.insertAdjacentHTML('beforeend',`<section class="content ideas-content"><div class="form-section"><div class="section-head">想吃清单 <small>${ideas.length} / 8 个想法</small></div><div id="options">${ideas.map((v,i)=>`<div class="option"><span class="swatch" style="background:${palette[i]}"></span><input data-index="${i}" aria-label="第${i+1}个想法" maxlength="12" value="${esc(v)}"><button data-delete="${i}" aria-label="删除${esc(v)}" >×</button></div>`).join('')}</div><form class="add" id="add-form"><input id="new-idea" aria-label="新增餐饮选项" placeholder="加一个想吃的…" maxlength="12" ${ideas.length>=8?'disabled':''}><button ${ideas.length>=8?'disabled':''}>＋ 添加</button></form><p class="error" id="idea-error" role="status"></p></div></section><footer class="bottom"><button class="primary" id="start">想好了，去转盘 <span style="float:right">→</span></button><div class="bottom-note">至少 2 个选项，即可开始</div></footer>`);
 // Commit every edit immediately, including invalid drafts, so no stale result survives a change.
 const drafts=()=>[...document.querySelectorAll('[data-index]')].map(e=>e.value.trim());
 const validate=()=>{const error=validateIdeas(drafts());$('#idea-error').textContent=error;$('#start').disabled=Boolean(error);return !error;};
 document.querySelectorAll('[data-index]').forEach(input=>input.addEventListener('input',()=>{choice=null;invalidateShops();rotation=0;validate();if(!validateIdeas(drafts(),0)){ideas=drafts();changed();}}));
 document.querySelectorAll('[data-delete]').forEach(button=>button.addEventListener('click',()=>{const next=drafts();next.splice(+button.dataset.delete,1);const error=validateIdeas(next,0);if(error){$('#idea-error').textContent=error;return;}ideas=next;changed();render();}));
 $('#add-form').addEventListener('submit',event=>{event.preventDefault();const next=[...drafts(),$('#new-idea').value.trim()];const error=validateIdeas(next,0);if(error){$('#idea-error').textContent=error;return;}ideas=next;changed();render();$('#new-idea').focus();});
 $('#start').addEventListener('click',()=>{if(!validate())return;ideas=drafts();move('wheel');});$('#start').disabled=Boolean(validateIdeas(ideas));}
function renderWheel(){app.insertAdjacentHTML('beforeend',`<section class="content wheel-content" aria-label="等概率餐饮选择转盘"><div class="wheel-area"><div class="pointer" aria-hidden="true"></div><div class="wheel" id="wheel" style="transform:rotate(${rotation}deg)"><svg viewBox="0 0 300 300" role="img" aria-label="${esc(ideas.join('、'))}">${ideas.map((label,i)=>{const a=(i*360/ideas.length-90)*Math.PI/180,b=((i+1)*360/ideas.length-90)*Math.PI/180,m=(a+b)/2;return `<path d="M150 150L${150+150*Math.cos(a)} ${150+150*Math.sin(a)}A150 150 0 ${b-a>Math.PI?1:0} 1 ${150+150*Math.cos(b)} ${150+150*Math.sin(b)}Z" fill="${palette[i]}" stroke="#fafbf7" stroke-width="2"/><text x="${150+94*Math.cos(m)}" y="${150+94*Math.sin(m)}" text-anchor="middle" dominant-baseline="middle" font-size="${ideas.length>5?13:16}" font-weight="700" fill="#3d4935">${esc(label.length>5?label.slice(0,4)+'…':label)}</text>`;}).join('')}</svg></div><button id="spin" class="hub" aria-label="转动转盘" ${busy?'disabled':''}>GO</button></div></section>`);$('#spin').addEventListener('click',spin);}
// Unlock sound in the GO gesture, before the asynchronous wheel animation ends.
let celebrationAudio=null,celebrationLayer=null,celebrationTimer=null,celebrationSounds=[];
function prepareCelebrationAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;celebrationAudio??=new Audio();if(celebrationAudio.state==='suspended')void celebrationAudio.resume().catch(()=>{});}catch{/* Sound is optional when blocked by the browser. */}}
function stopCelebration(){celebrationEpoch++;clearTimeout(celebrationTimer);celebrationLayer?.remove();celebrationLayer=null;for(const sound of celebrationSounds){try{sound.stop();}catch{}}celebrationSounds=[];}
let celebrationBufferPromise=null,celebrationEpoch=0;
function loadResultSound(){
 if(!celebrationBufferPromise&&celebrationAudio){
  celebrationBufferPromise=fetch('/success.wav').then(response=>{if(!response.ok)throw Error('Audio unavailable');return response.arrayBuffer();}).then(bytes=>celebrationAudio.decodeAudioData(bytes)).catch(()=>{celebrationBufferPromise=null;return null;});
 }
 return celebrationBufferPromise;
}
async function playResultSound(){const epoch=celebrationEpoch;try{
 const buffer=await loadResultSound(),ctx=celebrationAudio;
 if(!buffer||!ctx||ctx.state!=='running'||epoch!==celebrationEpoch||page!=='result'||document.hidden)return;
 const source=ctx.createBufferSource();source.buffer=buffer;source.connect(ctx.destination);celebrationSounds.push(source);source.onended=()=>source.disconnect();source.start();
}catch{/* An unavailable sound must never block the result page. */}}
function celebrateResult(){stopCelebration();if(document.hidden)return;void playResultSound();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const layer=document.createElement('div');layer.className='celebration-confetti';layer.setAttribute('aria-hidden','true');layer.style.cssText='position:fixed;inset:0;overflow:clip;pointer-events:none;z-index:10;contain:strict';document.body.append(layer);celebrationLayer=layer;
 const width=innerWidth,height=innerHeight;for(let i=0;i<80;i++){const piece=document.createElement('span'),x=Math.random()*width,drift=(Math.random()-.5)*200,turn=(Math.random()-.5)*1200;piece.style.cssText=`position:absolute;top:-24px;left:${x}px;width:${5+Math.random()*6}px;height:${10+Math.random()*12}px;border-radius:2px;background:${palette[i%palette.length]};will-change:transform`;layer.append(piece);piece.animate([{transform:'translate3d(0,-20px,0) rotate(0deg)',opacity:0},{transform:`translate3d(${drift*.2}px,${height*.18}px,0) rotate(${turn*.2}deg)`,opacity:1,offset:.2},{transform:`translate3d(${drift}px,${height+48}px,0) rotate(${turn}deg) rotateY(540deg)`,opacity:0}],{duration:2300+Math.random()*1000,delay:Math.random()*650,easing:'cubic-bezier(.2,.55,.45,1)',fill:'both'});}
 celebrationTimer=setTimeout(stopCelebration,4200);
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCelebration();});
async function spin(){if(busy)return;prepareCelebrationAudio();void loadResultSound();busy=true;choice=null;invalidateShops();$('#spin').disabled=true;$('.back').disabled=true;$('#spin').textContent='…';const index=uniform(ideas.length),from=rotation;rotation=targetRotation(rotation,index,ideas.length);const wheel=$('#wheel'),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?100:3000;const animation=wheel.animate([{transform:`rotate(${from}deg)`},{transform:`rotate(${rotation}deg)`}],{duration,easing:'cubic-bezier(.12,.75,.18,1)',fill:'forwards'});await animation.finished;wheel.style.transform=`rotate(${rotation}deg)`;animation.cancel();choice=ideas[index];busy=false;move('result');celebrateResult();}
function renderResult(){app.insertAdjacentHTML('beforeend',`<section class="content result-content"><div class="result-display" role="status"><span class="result-label">这次就吃</span><h2 id="chosen-category">${esc(choice)}</h2></div></section><footer class="bottom"><button class="primary" id="nearby">看看附近的${esc(choice)}店 →</button></footer>`);$('#nearby').addEventListener('click',()=>{move('shops');queryShops();});}
const states={idle:['选择查找位置','使用当前位置，或手动输入城市、区域。'],loading:['正在找附近的店',''],unconfigured:['商家数据未接入','暂时无法提供真实商家推荐。'],empty:['附近暂无匹配商家','试试扩大范围或更换区域。'],error:['暂时无法推荐商家','请稍后重试。'],denied:['定位未获授权','可以手动选择城市或区域。'],locationError:['定位失败','可以重试定位，或手动选择城市、区域。']};
function renderShops(){const state=states[status]||states.idle;app.insertAdjacentHTML('beforeend',`<section class="content shops-content"><h2 class="headline">${shops.length?`附近这 ${shops.length} 家，挑一家。`:'附近商家'}</h2><div class="loc"><span>⌖ ${esc(location?.label||'选择查找位置')}</span><button id="change-location">更改</button></div><div class="filters"><span class="filter" id="category-filter">${esc(choice)}</span><select id="radius" aria-label="查找范围">${[3,5,10].map(n=>`<option value="${n}" ${n===radius?'selected':''}>附近 ${n} 公里</option>`).join('')}</select>${shops.length?'<span class="filter">口碑优先</span>':''}</div><div class="shop-list" aria-live="polite" aria-busy="${status==='loading'}">${shops.length?shops.map(s=>`<button type="button" class="shop ${selected?.id===s.id?'selected':''}" data-shop="${esc(s.id)}" aria-pressed="${selected?.id===s.id}"><span class="shop-head"><span class="shop-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 10h16l-2 9H6zM3 10h18M9 3v3M15 3v3M8 22h8"/></svg></span><span><span class="shop-name">${esc(s.name)}</span></span><span class="radio"></span></span><span class="score">${s.rating==null?'':`<b>${s.rating} 分</b>`}${s.reviewCount==null?'':`<span>${s.reviewCount.toLocaleString()} 条评价</span>`}<span>${distance(s.distanceMeters)}</span></span>${s.positiveRate==null?'':`<span class="address">好评率 ${s.positiveRate}%</span>`}${s.address?`<span class="address" style="display:block">${esc(s.address)}</span>`:''}<span class="address" style="display:block">${s.location.lng.toFixed(5)}, ${s.location.lat.toFixed(5)}</span></button>`).join(''):`<div class="empty-state"><div class="empty-icon ${status==='loading'?'loading':''}">⌖</div><h2>${state[0]}</h2><p>${esc(message||state[1])}</p>${status==='loading'?'':`<button class="secondary" id="state-action">${status==='error'?'重新查询':'选择城市或区域'}</button>`}</div>`}${shops.length>0&&shops.length<3&&radius<10?`<button class="secondary" id="expand">只有 ${shops.length} 家，扩大到 ${radius===3?5:10} 公里</button>`:''}</div>${shops.length?`<p class="why">数据来源：${esc(source)}<br>在来源返回的商家中，按评分、距离排序；缺失评分排后。仅展示最多 3 家，不代表附近全部商家。${shops.some(s=>s.demo)?'<br>演示模式 · 虚构商家，不可导航。':''}</p>`:''}</section><footer class="bottom"><button class="primary" id="choose-shop" ${selected?'':'disabled'}>就选这家 →</button><div class="bottom-note">${selected?`已选：${esc(selected.name)}`:'请先选择一家商家'}</div></footer>`);
 $('#change-location').onclick=openLocation;$('#radius').onchange=event=>{radius=+event.target.value;invalidateShops();queryShops();};$('#state-action')?.addEventListener('click',()=>status==='error'?queryShops():openLocation());$('#expand')?.addEventListener('click',()=>{radius=radius===3?5:10;invalidateShops();queryShops();});document.querySelectorAll('[data-shop]').forEach(button=>button.onclick=()=>{selected=shops.find(s=>s.id===button.dataset.shop);render();$(`[data-shop="${CSS.escape(selected.id)}"]`)?.focus({preventScroll:true});});$('#choose-shop').onclick=()=>{if(selected)move('destination');};}
async function api(path,signal){const timeout=AbortSignal.timeout(18000);const response=await fetch(path,{signal:signal?AbortSignal.any([signal,timeout]):timeout,cache:'no-store',credentials:'omit'});let data;try{data=await response.json();}catch{throw Error('服务返回异常，请稍后重试。');}if(!response.ok){const error=new Error(data.message||'查询失败，请稍后重试。');error.code=data.code;throw error;}return data;}
async function queryShops(){invalidateShops();const id=requestId;controller=new AbortController();status='loading';if(page==='shops')render();try{const config=await api('/api/config',controller.signal);if(id!==requestId)return;if(!config.configured){status='unconfigured';return;}if(!location){status='loading';if(page==='shops')render();try{const located=await new Promise((resolve,reject)=>{if(!navigator.geolocation){reject({code:2});return;}navigator.geolocation.getCurrentPosition(p=>resolve({kind:'coordinates',label:'当前位置',lng:p.coords.longitude,lat:p.coords.latitude,coordType:'wgs84'}),reject,{timeout:12000,maximumAge:60000,enableHighAccuracy:true});});if(id!==requestId)return;location=located;}catch(error){if(id!==requestId)return;status=error.code===1?'denied':'locationError';return;}}const params=new URLSearchParams({category:choice,radius:String(radius),location:JSON.stringify(location)});const data=await api(`${config.workerBaseUrl||''}/api/shops?${params}`,controller.signal);if(id!==requestId)return;shops=data.shops;source=data.source;status=shops.length?'ready':'empty';}catch(error){if(id!==requestId||error.name==='AbortError')return;status=error.code==='NOT_CONFIGURED'?'unconfigured':'error';message=error.message;}finally{if(id===requestId&&page==='shops')render();}}
function renderDestination(){const s=selected;app.insertAdjacentHTML('beforeend',`<section class="content destination-content"><div class="success-icon">✓</div><div class="destination"><span class="mini-pill">本次聚餐目的地</span><h2>${esc(s.name)}</h2>${s.address?`<p>${esc(s.address)}</p>`:''}<div class="trip"><div><strong>${distance(s.distanceMeters)}</strong><span>距查找位置</span></div><div><strong>驾车</strong><span>在地图中查看路线</span></div></div></div><div class="navigation-options"><button data-map="amap" class="${provider==='amap'?'active':''}" aria-pressed="${provider==='amap'}">高德地图</button><button data-map="baidu" class="${provider==='baidu'?'active':''}" aria-pressed="${provider==='baidu'}">百度地图</button></div>${s.demo?'<p class="why">演示商家 · 不可发起真实导航</p>':''}</section><footer class="bottom">${s.demo?'<button class="primary" disabled>演示模式 · 不可导航</button>':`<a class="primary" id="navigate" href="${esc(navigationURL(s,provider))}" target="_blank" rel="noopener noreferrer">出发，打开导航 ↗</a>`}</footer>`);document.querySelectorAll('[data-map]').forEach(button=>button.onclick=()=>{provider=button.dataset.map;render();});}
function openLocation(){$('#location-error').textContent='';$('#region').value=location?.kind==='region'?location.label:'';$('#location-dialog').showModal();$('#region').focus();}
$('#close-location').onclick=()=>$('#location-dialog').close();$('#location-dialog').addEventListener('close',()=>{locationRequest++;$('#locate').disabled=false;$('#locate').textContent='使用当前位置';});
$('#location-form').onsubmit=event=>{event.preventDefault();const label=$('#region').value.trim();if(!label){$('#location-error').textContent='请输入城市或区域。';return;}location={kind:'region',label};invalidateShops();$('#location-dialog').close();queryShops();};
$('#locate').onclick=()=>{const id=++locationRequest;invalidateShops();location=null;$('#location-error').textContent='正在定位…';$('#locate').disabled=true;$('#locate').textContent='正在定位…';const fail=error=>{if(id!==locationRequest)return;status=error?.code===1?'denied':'locationError';message='';$('#location-error').textContent=states[status][0]+'，请手动输入城市或区域。';$('#locate').disabled=false;$('#locate').textContent='重试定位';if(page==='shops')render();};if(!navigator.geolocation){fail();return;}navigator.geolocation.getCurrentPosition(position=>{if(id!==locationRequest)return;location={kind:'coordinates',label:'当前位置',lng:position.coords.longitude,lat:position.coords.latitude,coordType:'wgs84'};$('#location-dialog').close();queryShops();},fail,{enableHighAccuracy:true,timeout:12000,maximumAge:60000});};
// Keep the existing navigation button; mobile tries Baidu's app URI, then its web route.
let navigationFallback=null;
function cancelNavigationFallback(){clearTimeout(navigationFallback);navigationFallback=null;}
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelNavigationFallback();});
window.addEventListener('pagehide',cancelNavigationFallback);
document.addEventListener('click',event=>{const link=event.target.closest?.('#navigate');if(!link||provider!=='baidu'||!/Android|iPhone|iPad|iPod/i.test(navigator.userAgent))return;
 event.preventDefault();cancelNavigationFallback();const web=link.href,params=new URL(web).searchParams;params.delete('output');params.delete('origin');params.set('src',/Android/i.test(navigator.userAgent)?'andr.justpick.meal':'ios.justpick.meal');
 navigationFallback=setTimeout(()=>{if(!document.hidden&&page==='destination')window.location.assign(web);},1600);
 window.location.assign('baidumap://map/direction?'+params.toString());
});
render();





